SELECT COUNT(*) AS "count_result" FROM triples t0, triples t1, triples t2, triples t3, triples t4, triples t5 WHERE t0.p = 'http://schema.org/contentRating' AND struct_pack(kind := 0::UTINYINT, value := t1.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t1.p = 'http://schema.org/contentSize' AND struct_pack(kind := 0::UTINYINT, value := t2.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t2.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/hasGenre' AND t2.o = struct_pack(kind := 0::UTINYINT, value := 'http://db.uwaterloo.ca/~galuc/wsdbm/SubGenre83', datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t3.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/makesPurchase' AND struct_pack(kind := 0::UTINYINT, value := t4.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = t3.o AND t4.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/purchaseDate' AND struct_pack(kind := 0::UTINYINT, value := t5.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = t3.o AND t5.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/purchaseFor' AND t5.o = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR)